const item = $input.first().json;
let output = (item.text ?? item.output ?? '').toString();
output = output.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
// Bloque pitwall-meta (razonamiento + sugerencias). Tolerante a JSON imperfecto de modelos locales.
const parseMeta = (txt) => {
  let meta = { razonamiento: '', sugerencias: [] };
  let m = txt.match(/```\s*pitwall-meta\s*([\s\S]*?)```/i) || txt.match(/```\s*(?:json)?\s*(\{[\s\S]*?"sugerencias"[\s\S]*?\})\s*```/i);
  if (!m) return { meta, cleaned: txt };
  const body = m[1];
  try { meta = { ...meta, ...JSON.parse(body) }; }
  catch (e) {
    const r = body.match(/"razonamiento"\s*:\s*"((?:[^"\\]|\\.)*)"/);
    if (r) meta.razonamiento = r[1];
    const s = body.match(/"sugerencias"\s*:\s*\[([\s\S]*?)\]/);
    if (s) meta.sugerencias = [...s[1].matchAll(/"((?:[^"\\]|\\.)*)"/g)].map(x => x[1]);
  }
  return { meta, cleaned: txt.replace(m[0], '').trim() };
};
const parsed = parseMeta(output);
let meta = parsed.meta;
output = parsed.cleaned;
const steps = [
  { tipo: 'razonamiento', titulo: 'Respondió sin consultar la base de conocimiento', detalle: 'Modo directo: solo conocimiento general del modelo, sin recuperación de información.' }
];
if (meta.razonamiento) steps.push({ tipo: 'razonamiento', titulo: 'En qué se basó', detalle: meta.razonamiento });
// Si el modelo no entregó sugerencias, se ofrecen preguntas de arranque sobre la F1 2026
const SUGERENCIAS_BASE = ['¿Qué cambió en la F1 en 2026?', '¿Quién va ganando el campeonato?', '¿Cómo funciona un fin de semana con sprint?', '¿Qué es el Overtake Mode?'];
let sugerencias = Array.isArray(meta.sugerencias) ? meta.sugerencias.map(String).filter(s => s.trim()).slice(0, 4) : [];
if (sugerencias.length === 0) sugerencias = SUGERENCIAS_BASE.slice(0, 3);
let sessionId = '';
try { sessionId = $('Cuando llega un mensaje').first().json.sessionId || ''; } catch (e) {}
return [{ json: { output, steps, sources: [], suggestions: sugerencias, razonamiento: meta.razonamiento || '', mode: 'directo', sessionId } }];
